with flattened as (select id, plan, effective_from, currency, explode_outer(tier_limits) as element from price_tiers) select plan, effective_from, currency, max(element) over w_grp currency_max_element, stddev_samp(element) over w_grp currency_stddev_samp_element, cume_dist() over w_grp_2 element_cume_dist from flattened window w_grp as (partition by currency), w_grp_2 as (order by element);
